// itx8Net1D is itx16Net1D for the 8-point networks (n is 4 or 8).
func itx8Net1D(t tx1DType, n int, in *[8]archsimd.Int16x8, out *[8]archsimd.Int16x8) {
	if t == tx1DDCT {
		itx8Net(in, out)
		return
	}
	if n <= 4 {
		itx8ADSTNet4(in, out)
	} else {
		itx8ADSTNet8(in, out)
	}
	if t == tx1DFlipADST {
		for i := 0; i < 4; i++ {
			out[i], out[7-i] = out[7-i], out[i]
		}
	}
}
